html:
{% set company = frappe.get_doc("Company", doc.company) if doc.company else None %}

<style>
    @page {
        size: A4 portrait;
        margin: 12mm;
    }

    body {
        font-family: Arial, sans-serif;
        font-size: 11px;
        color: #222;
    }

    .print-wrapper {
        width: 100%;
    }

    .header-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 12px;
    }

    .company-logo {
        width: 80px;
        max-height: 70px;
        object-fit: contain;
    }

    .company-name {
        font-size: 20px;
        font-weight: bold;
        text-transform: uppercase;
        margin-bottom: 4px;
    }

    .company-address {
        font-size: 10px;
        color: #555;
        line-height: 1.4;
    }

    .document-title {
        text-align: center;
        font-size: 18px;
        font-weight: bold;
        text-transform: uppercase;
        padding: 8px;
        border: 1px solid #222;
        margin-bottom: 12px;
        background: #f2f2f2;
        letter-spacing: 0.5px;
    }

    .info-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 12px;
    }

    .info-table td {
        border: 1px solid #999;
        padding: 7px 8px;
        vertical-align: top;
    }

    .info-label {
        font-weight: bold;
        background: #f7f7f7;
        width: 15%;
        white-space: nowrap;
    }

    .employee-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 8px;
        font-size: 10px;
        color: black;
    }

    .employee-table th {
        border: 1px solid #555;
        padding: 7px 5px;
        text-align: center;
        background: #e9e9e9;
        font-weight: bold;
        white-space: nowrap;
        color: black !important;
    }

    .employee-table td {
        border: 1px solid #777;
        padding: 6px 5px;
        vertical-align: middle;
        color: black !important;
    }

    .text-center {
        text-align: center;
    }

    .text-right {
        text-align: right;
    }

    .text-left {
        text-align: left;
    }

    .summary-box {
        width: 45%;
        margin-left: auto;
        margin-top: 12px;
        border-collapse: collapse;
    }

    .summary-box td {
        border: 1px solid #555;
        padding: 8px;
    }

    .summary-label {
        font-weight: bold;
        background: #f2f2f2;
    }

    .amount-highlight {
        font-weight: bold;
        font-size: 12px;
    }

    .signature-section {
        width: 100%;
        margin-top: 45px;
        border-collapse: collapse;
    }

    .signature-section td {
        width: 33.33%;
        text-align: center;
        padding-top: 35px;
    }

    .signature-line {
        border-top: 1px solid #333;
        display: inline-block;
        width: 80%;
        padding-top: 6px;
        font-weight: bold;
    }

    .footer-note {
        margin-top: 18px;
        font-size: 9px;
        color: #666;
        text-align: center;
        border-top: 1px solid #ddd;
        padding-top: 6px;
    }

    .no-break {
        page-break-inside: avoid;
    }
</style>

<div class="print-wrapper">

    <!-- Header -->
    <table class="header-table">
        <tr>
            <td style="width: 18%; vertical-align: top;">
                {% if company and company.company_logo %}
                    <img src="{{ company.company_logo }}" class="company-logo">
                {% endif %}
            </td>

            <td style="width: 64%; text-align: center; vertical-align: top;">
                <div class="company-name">
                    {{ doc.company or "" }}
                </div>

                {% if company %}
                    <div class="company-address">
                        {% if company.address_html %}
                            {{ company.address_html }}
                        {% endif %}
                    </div>
                {% endif %}
            </td>

            <td style="width: 18%; text-align: right; vertical-align: top;">
                <b>Print Date:</b><br>
                {{ frappe.utils.formatdate(frappe.utils.today(), "dd-MM-yyyy") }}
            </td>
        </tr>
    </table>

    <!-- Title -->
    <div class="document-title">
        Leave Encashment Bulk
    </div>

    <!-- Main Info -->
    <table class="info-table no-break">
        <tr>
            <td class="info-label">Document No.</td>
            <td>{{ doc.name }}</td>

            <td class="info-label">Company</td>
            <td>{{ doc.company or "" }}</td>
        </tr>

        <tr>
            <td class="info-label">Leave Period</td>
            <td>{{ doc.leave_period or "" }}</td>

            <td class="info-label">Leave Type</td>
            <td>{{ doc.leave_type or "" }}</td>
        </tr>

        <tr>
            <td class="info-label">Encashment Date</td>
            <td>
                {% if doc.encashment_date %}
                    {{ frappe.utils.formatdate(doc.encashment_date, "dd-MM-yyyy") }}
                {% endif %}
            </td>

            <td class="info-label">Employment Type</td>
            <td>{{ doc.employment_type or "" }}</td>
        </tr>

        <tr>
            <td class="info-label">Submit Encashment</td>
            <td>
                {% if doc.submit_leave_encashment %}
                    Yes
                {% else %}
                    No
                {% endif %}
            </td>

            <td class="info-label">Status</td>
            <td>
                {% if doc.docstatus == 0 %}
                    Draft
                {% elif doc.docstatus == 1 %}
                    Submitted
                {% elif doc.docstatus == 2 %}
                    Cancelled
                {% endif %}
            </td>
        </tr>
    </table>

    <!-- Employees Table -->
    <table class="employee-table">
        <thead>
            <tr>
                <th style="width: 4%;">Sr</th>
                <th style="width: 11%;">Employee</th>
                <th style="width: 18%;">Employee Name</th>
                <th style="width: 13%;">Employment Type</th>
                <th style="width: 9%;">Leave Balance</th>
                <th style="width: 10%;">Actual Encashable Days</th>
                <th style="width: 9%;">Encashment Days</th>
                <th style="width: 12%;">Encashment Amount</th>
                <th style="width: 9%;">Status</th>
                <th style="width: 15%;">Remarks</th>
            </tr>
        </thead>

        <tbody>
            {% for row in doc.employees %}
            <tr>
                <td class="text-center">{{ loop.index }}</td>

                <td class="text-center">
                    {{ row.employee or "" }}
                </td>

                <td class="text-left">
                    {{ row.employee_name or "" }}
                </td>

                <td class="text-left">
                    {{ row.employment_type or "" }}
                </td>

                <td class="text-right">
                    {{ frappe.utils.flt(row.leave_balance, 2) }}
                </td>

                <td class="text-right">
                    {{ frappe.utils.flt(row.actual_encashable_days, 2) }}
                </td>

                <td class="text-right">
                    {{ frappe.utils.flt(row.encashment_days, 2) }}
                </td>

                <td class="text-right">
                    {{ frappe.utils.fmt_money(row.encashment_amount or 0, currency=doc.currency if doc.get("currency") else None) }}
                </td>

                <td class="text-center">
                    {{ row.status or "" }}
                </td>

                <td class="text-left">
                    {{ row.remarks or "" }}
                </td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- Summary -->
    <table class="summary-box no-break">
        <tr>
            <td class="summary-label">Total Employees</td>
            <td class="text-right amount-highlight">
                {{ doc.total_employees or (doc.employees | length) }}
            </td>
        </tr>

        <tr>
            <td class="summary-label">Total Encashment Amount</td>
            <td class="text-right amount-highlight">
                {{ frappe.utils.fmt_money(doc.total_encashment_amount or 0, currency=doc.currency if doc.get("currency") else None) }}
            </td>
        </tr>
    </table>

    <!-- Signatures -->
    <table class="signature-section no-break">
        <tr>
            <td>
                <span class="signature-line">Prepared By</span>
            </td>
            <td>
                <span class="signature-line">Checked By</span>
            </td>
            <td>
                <span class="signature-line">Approved By</span>
            </td>
        </tr>
    </table>

    <div class="footer-note">
        This is a system generated Leave Encashment Bulk print.
    </div>

</div>
